from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class IpConnectivityTestResult(SchemaObject):
    lost_packets = SchemaField(name="lostPackets")
    lost_packets_percent = SchemaField(name="lostPacketsPercent")
    received_packets = SchemaField(name="receivedPackets")
    sent_packets = SchemaField(name="sentPackets")
    avg_round_trip_time = SchemaField(name="avgRoundTripTime")
    max_round_trip_time = SchemaField(name="maxRoundTripTime")
    min_round_trip_time = SchemaField(name=" minRoundTripTime")
    ping_reply_list = SchemaField(name="pingTeplyList")

    def __init__(self, lost_packets, lost_packets_percent, received_packets, sent_packets, avg_round_trip_time,
                 max_round_trip_time, min_round_trip_time, ping_reply_list):
        self.lost_packets = lost_packets
        self.lost_packets_percent = lost_packets_percent
        self.received_packets = received_packets
        self.sent_packets = sent_packets
        self.avg_round_trip_time = avg_round_trip_time
        self.max_round_trip_time = max_round_trip_time
        self.min_round_trip_time = min_round_trip_time
        self.ping_reply_list = ping_reply_list
        super(IpConnectivityTestResult, self).__init__()


class IpConnectivityStatusTRSV1(SchemaObject):
    status = SchemaField(name="status")
    reason = SchemaField(name="reason")
    result = SchemaField(name="result", klass=IpConnectivityTestResult)

    def __init__(self, status, reason, result):
        self.status = status
        self.reason = reason
        self.result = result
        super(IpConnectivityStatusTRSV1, self).__init__()
